#include <stdlib.h>
#include <string.h>

OM_uint32 process_spnego_continuation(OM_uint32 *minstat, gss_buffer_t buf, gss_ctx_id_t *ctx, gss_buffer_t *responseToken, gss_buffer_t *mechListMIC, OM_uint32 *negState, send_token_flag *return_token) {
    OM_uint32 status = 0;

    if (!minstat || !buf || !ctx || !responseToken || !mechListMIC || !negState || !return_token) {
        return (OM_UINT32_MAX);
    }

    if (buf->length <= 0 || buf->value == NULL) {
        return (GSS_S_BAD_SIG);
    }

    if (buf->length > (size_t)(-1) / 2) {
        return (GSS_S_FAILURE);
    }

    if (responseToken->length <= 0) {
        responseToken->value = NULL;
    } else {
        responseToken->value = (void*)malloc(responseToken->length);
        if (!responseToken->value) {
            return (GSS_S_FAILURE);
        }
    }

    if (mechListMIC->length <= 0) {
        mechListMIC->value = NULL;
    } else {
        mechListMIC->value = (void*)malloc(mechListMIC->length);
        if (!mechListMIC->value) {
            free(responseToken->value);
            responseToken->value = NULL;
            return (GSS_S_FAILURE);
        }
    }

    *return_token = 0;
    *negState = 0;

    if (buf->length < 4) {
        free(responseToken->value);
        free(mechListMIC->value);
        responseToken->value = NULL;
        mechListMIC->value = NULL;
        return (GSS_S_BAD_SIG);
    }

    if (((unsigned char*)buf->value)[0] != 0x60) {
        free(responseToken->value);
        free(mechListMIC->value);
        responseToken->value = NULL;
        mechListMIC->value = NULL;
        return (GSS_S_BAD_SIG);
    }

    *minstat = 0;
    *ctx = NULL;

    return (GSS_S_CONTINUE_NEEDED);
}
